import java.util.ArrayList;
import java.util.List;

class ArticulationPoints {

    private static final int NO_PARENT = -1;

    /** Undirected graph backed by an adjacency list. */
    static class Graph {
        final int V;
        final List<List<Integer>> adj;

        Graph(int V, int[][] edges) {
            this.V = V;
            List<List<Integer>> a = new ArrayList<>();
            for (int i = 0; i < V; i++) a.add(new ArrayList<>());
            for (int[] edge : edges) {
                a.get(edge[0]).add(edge[1]);
                a.get(edge[1]).add(edge[0]);
            }
            adj = a;
        }
    }

    private static class DfsState {
        final boolean[] visited;
        final boolean[] isAP;
        final int[] disc;
        final int[] low;
        int timer;

        DfsState(int V) {
            visited = new boolean[V];
            isAP = new boolean[V];
            disc = new int[V];
            low = new int[V];
        }
    }

    private static void dfs(Graph graph, int u, int parent, DfsState state) {
        state.visited[u] = true;
        state.disc[u] = state.low[u] = ++state.timer;
        int children = 0;

        for (int v : graph.adj.get(u)) {
            if (!state.visited[v]) {
                children++;
                dfs(graph, v, u, state);
                state.low[u] = Math.min(state.low[u], state.low[v]);
                if (parent != NO_PARENT && state.low[v] >= state.disc[u]) {
                    state.isAP[u] = true;
                }
            } else if (v != parent) {
                state.low[u] = Math.min(state.low[u], state.disc[v]);
            }
        }

        if (parent == NO_PARENT && children > 1) {
            state.isAP[u] = true;
        }
    }

    /**
     * Returns all articulation points in the graph, or [-1] if none exist.
     *
     * @param graph undirected graph to search
     */
    static List<Integer> articulationPoints(Graph graph) {
        if (graph == null || graph.V <= 0) return new ArrayList<>();

        DfsState state = new DfsState(graph.V);
        for (int u = 0; u < graph.V; u++) {
            if (!state.visited[u]) {
                dfs(graph, u, NO_PARENT, state);
            }
        }

        List<Integer> result = new ArrayList<>();
        for (int u = 0; u < graph.V; u++) {
            if (state.isAP[u]) result.add(u);
        }

        if (result.isEmpty()) result.add(-1);
        return result;
    }

    public static void main(String[] args) {
        Graph graph = new Graph(5, new int[][]{{0, 1}, {1, 4}, {2, 3}, {2, 4}, {3, 4}});
        List<Integer> ans = articulationPoints(graph);

        for (int u : ans) System.out.print(u + " ");
        System.out.println();
    }
}

